import React, { useEffect, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import authService from '../services/authService';
import { Eye, EyeOff } from 'lucide-react';

const VERIFICATION_REDIRECT_KEY = 'carvex.login.verificationRedirect';
const VERIFICATION_REDIRECT_MAX_AGE = 30 * 60 * 1000;

function getSafeLocalRedirect(value) {
    if (typeof value !== 'string' || !value.startsWith('/') || value.startsWith('//') || value.includes('\\')) {
        return null;
    }

    try {
        const target = new URL(value, window.location.origin);
        if (target.origin !== window.location.origin) return null;
        return `${target.pathname}${target.search}${target.hash}`;
    } catch {
        return null;
    }
}

function getSavedVerificationRedirect() {
    try {
        const saved = JSON.parse(window.localStorage.getItem(VERIFICATION_REDIRECT_KEY) || 'null');
        if (!saved || Date.now() - saved.savedAt > VERIFICATION_REDIRECT_MAX_AGE) return null;
        return getSafeLocalRedirect(saved.path);
    } catch {
        return null;
    }
}

export default function Login() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [googleLoading, setGoogleLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [verificationRequired, setVerificationRequired] = useState(false);
    const [resendLoading, setResendLoading] = useState(false);
    const [resendMessage, setResendMessage] = useState('');
    const [resendError, setResendError] = useState('');
    const { login, user } = useAuth();
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const redirectFromQuery = getSafeLocalRedirect(searchParams.get('redirect'));
    const verificationComplete = searchParams.get('verified') === '1';
    const redirectAfterVerification = verificationComplete ? getSavedVerificationRedirect() : null;
    const redirectAfterLogin = redirectFromQuery || redirectAfterVerification;

    useEffect(() => {
        try {
            if (redirectFromQuery) {
                window.localStorage.setItem(VERIFICATION_REDIRECT_KEY, JSON.stringify({
                    path: redirectFromQuery,
                    savedAt: Date.now(),
                }));
            } else if (!verificationComplete) {
                window.localStorage.removeItem(VERIFICATION_REDIRECT_KEY);
            }
        } catch {
            // Login should still work when browser storage is unavailable.
        }
    }, [redirectFromQuery, verificationComplete]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        setVerificationRequired(false);
        setLoading(true);
        try {
            const data = await login(email, password);
            if (redirectAfterLogin) {
                try {
                    window.localStorage.removeItem(VERIFICATION_REDIRECT_KEY);
                } catch {
                    // Storage cleanup is best-effort.
                }
                navigate(redirectAfterLogin, { replace: true });
                return;
            }

            // Redirect based on user role when there is no safe local destination.
            const userData = data?.user || user;
            const isAdmin = userData?.role === 'admin' || userData?.is_admin === true;
            if (isAdmin) {
                navigate('/admin/dashboard');
            } else {
                navigate('/dashboard/overview');
            }
        } catch (err) {
            const responseData = err.response?.data || {};
            const requiresVerification = responseData.requires_email_verification === true
                || responseData.email_verification_required === true
                || (err.response?.status === 403 && responseData.email_verified === false);
            setVerificationRequired(requiresVerification);
            setError(requiresVerification ? '' : responseData.message || 'Login failed. Please check your credentials.');
        } finally {
            setLoading(false);
        }
    };

    const handleResendVerification = async () => {
        setResendLoading(true);
        setResendMessage('');
        setResendError('');
        try {
            const response = await authService.resendVerification({ email, password });
            setResendMessage(response?.data?.message || 'If this account needs verification, a fresh link has been sent. Check your inbox and spam folder.');
        } catch {
            setResendError('We could not request a new verification email. Please try again in a moment.');
        } finally {
            setResendLoading(false);
        }
    };

    const handleGoogleLogin = async () => {
        setError('');
        setGoogleLoading(true);
        let shouldResetLoading = true;

        try {
            const redirectTo = `${window.location.origin}/auth/callback`;
            const response = await authService.getSocialAuthUrl('google', redirectTo);
            const authUrl = response?.data?.url;

            if (authUrl) {
                shouldResetLoading = false;
                window.location.href = authUrl;
                return;
            }

            setError('Google authentication is unavailable right now. Please sign in with your email and password.');
        } catch (err) {
            setError(err.response?.data?.message || 'Could not connect to Google. Please try again.');
        } finally {
            if (shouldResetLoading) setGoogleLoading(false);
        }
    };

    return (
        <div className="auth-page auth-page--login">
            <div className="auth-container auth-container--login">
                <div className="auth-shell auth-shell--login">
                    <aside className="auth-visual-panel" aria-label="CarVex access benefits">
                        <div className="auth-visual-panel__content">
                            <span className="auth-visual-panel__eyebrow">Built for drivers &amp; sellers</span>
                            <h2>Find the right part without the guesswork.</h2>
                            <p>Track orders, save favorite parts, and shop trusted listings from people who know your ride.</p>
                            <ul>
                                <li>Faster reorders and saved carts</li>
                                <li>Verified sellers and local inventory</li>
                                <li>One place for parts, service, and support</li>
                            </ul>
                        </div>
                    </aside>

                    <section className="auth-modal auth-modal--login" aria-labelledby="login-heading">
                        <div className="auth-modal__header auth-modal__header--login">
                            <Link to="/" className="auth-brand" aria-label="CarVex home">
                                <span className="auth-brand__mark" aria-hidden="true">C</span>
                                <span>CarVex</span>
                            </Link>
                            <button
                                type="button"
                                className="auth-modal__close"
                                aria-label="Close sign in"
                                onClick={() => navigate('/')}
                            >
                                <span aria-hidden="true">x</span>
                            </button>
                            <span className="auth-eyebrow">Customer and seller access</span>
                            <h1 id="login-heading">Welcome back</h1>
                            <p className="auth-modal__subtitle">Sign in to continue to your CarVex account.</p>
                        </div>
                        <div className="auth-modal__body">
                            {error && <div className="alert alert-danger" role="alert">{error}</div>}
                            {verificationComplete ? (
                                <div className="auth-verification-notice" role="status">
                                    Your email has been verified. Sign in to continue.
                                </div>
                            ) : null}
                            {verificationRequired ? (
                                <div className="auth-verification-notice" role="status">
                                    <strong>Verify your email to sign in</strong>
                                    <p>We sent a verification link when you registered. Check your inbox and spam folder.</p>
                                    <button type="button" onClick={handleResendVerification} disabled={resendLoading || !email || !password}>
                                        {resendLoading ? 'Sending...' : 'Resend verification email'}
                                    </button>
                                    {resendMessage ? <small role="status">{resendMessage}</small> : null}
                                    {resendError ? <small role="alert">{resendError}</small> : null}
                                </div>
                            ) : null}

                            <button
                                type="button"
                                className="auth-google-button"
                                onClick={handleGoogleLogin}
                                disabled={googleLoading || loading}
                                aria-busy={googleLoading}
                            >
                                <GoogleMark />
                                <span>{googleLoading ? 'Connecting to Google...' : 'Continue with Google'}</span>
                            </button>
                            <div className="auth-divider"><span>or sign in with email</span></div>

                            <form onSubmit={handleSubmit} className="auth-form">
                                <div className="form-group">
                                    <label htmlFor="email">Email address</label>
                                    <input
                                        id="email"
                                        type="email"
                                        value={email}
                                        onChange={(e) => { setEmail(e.target.value); setVerificationRequired(false); }}
                                        placeholder="your@email.com"
                                        required
                                        autoComplete="email"
                                        inputMode="email"
                                        disabled={loading || googleLoading}
                                    />
                                </div>
                                <div className="form-group">
                                    <div className="auth-label-row">
                                        <label htmlFor="password">Password</label>
                                        <Link to="/forgot-password" className="auth-link-muted">
                                            Forgot password?
                                        </Link>
                                    </div>
                                    <div className="auth-password-field">
                                        <input
                                            id="password"
                                            type={showPassword ? 'text' : 'password'}
                                            value={password}
                                            onChange={(e) => { setPassword(e.target.value); setVerificationRequired(false); }}
                                            placeholder="Enter your password"
                                            required
                                            autoComplete="current-password"
                                            disabled={loading || googleLoading}
                                        />
                                        <button
                                            type="button"
                                            className="auth-password-toggle auth-password-toggle--icon"
                                            onClick={() => setShowPassword((visible) => !visible)}
                                            aria-label={showPassword ? 'Hide password' : 'Show password'}
                                            aria-pressed={showPassword}
                                        >
                                            {showPassword ? <EyeOff size={17} /> : <Eye size={17} />}
                                        </button>
                                    </div>
                                </div>
                                <button
                                    type="submit"
                                    className="btn btn-primary btn-block"
                                    disabled={loading || googleLoading}
                                    aria-busy={loading}
                                >
                                    {loading ? 'Signing in...' : 'Sign In'}
                                </button>
                            </form>
                            <div className="auth-footer">
                                <p>Don't have an account? <Link to="/register" className="auth-link">Sign up</Link></p>
                            </div>
                        </div>
                    </section>
                </div>
            </div>
        </div>
    );
}

function GoogleMark() {
    return (
        <svg className="google-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
            <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
            <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
            <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
            <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
        </svg>
    );
}
